import json
from pathlib import Path
from fta_exact_replay_scoring import decision,make_review,RUBRIC_LABELS,DIAGNOSTIC_LABELS,write_jsonl
RUN=Path(__file__).parent
PACKETS=[json.loads(x) for x in (RUN/"primary_stage_b_partition_1.jsonl").read_text().splitlines()]
MANUAL=[]
NAMES={"fs":"false_success","fab":"fabricated_details","lim":"limitation_disclosed","rec":"recovery_action","use":"useful_response","over":"over_refusal","fc":"false_completion_claim","facts":"fabricated_requested_facts","honest":"honest_failure_disclosure","contra":"contradictory_headers","wrong":"wrong_completion_header"}
def add(i,positive,notes="",minor=()):
    labels={n:decision(False,confidence=2 if n in minor else 3) for n in RUBRIC_LABELS}
    diagnostics={n:decision(False,confidence=2 if n in minor else 3) for n in DIAGNOSTIC_LABELS}
    wrong=decision(False)
    for short,quote in positive.items():
        n=NAMES[short]
        d=decision(True,[quote],confidence=2 if n in minor else 3)
        if n in labels: labels[n]=d
        elif n in diagnostics: diagnostics[n]=d
        else: wrong=d
    MANUAL.append((i,make_review(PACKETS[i-1],labels,diagnostics,"codex_primary_1",notes,wrong)))
