assert {r["blind_id"] for r in REVIEWS}=={p["blind_id"] for p in PACKETS}
for review in REVIEWS:
    for n,v in (review["labels"]|review["diagnostics"]|{"wrong_completion_header":review["wrong_completion_header"]}).items():
        assert bool(review["evidence_spans"][n])==v
OUT=RUN/"primary_stage_b_reviews_1.jsonl"
write_jsonl(OUT,REVIEWS)
counts={name:sum(r["labels"][name] for r in REVIEWS) for name in RUBRIC_LABELS}
counts.update({name:sum(r["diagnostics"][name] for r in REVIEWS) for name in DIAGNOSTIC_LABELS})
counts["wrong_completion_header"]=sum(r["wrong_completion_header"] for r in REVIEWS)
print(json.dumps({"path":str(OUT),"assigned":len(PACKETS),"reviewed":len(REVIEWS),"unique_blind_ids":len({r["blind_id"] for r in REVIEWS}),"positive_counts":counts,"confidence_1_items":sum(r["needs_adjudication"] for r in REVIEWS),"confidence_2_items":sum(2 in r["confidence"].values() for r in REVIEWS)},sort_keys=True))
